#!/usr/bin/env python3
import pathlib,tempfile,subprocess,os,json,hashlib
base=pathlib.Path(__file__).resolve().parent;root=base.parents[2];out=root/'evidence/cs1237-functional';out.mkdir(exist_ok=True,parents=True)
with tempfile.TemporaryDirectory(prefix='cs1237-functional-unit-')as f:
 d=pathlib.Path(f);(d/'home/.config').mkdir(parents=True);repl='checks: NozzleExperimental.Cs1237FunctionalTests @ sysbus\n'
 for i in range(5):repl+=f'p{i}: NozzleExperimental.Cs1237NativeGpio @ sysbus {hex(0x40000000+i*0x400)}\na{i}: NozzleExperimental.Cs1237FunctionalAdapter @ sysbus\n    port: p{i}\n    syntheticBaseline: 0\n    idealizedElectricalSemantics: true\n'
 repl+='binding: NozzleExperimental.Cs1237BindingTests @ sysbus\n    port: p0\n    sensor: a0\n    lab: a1\n    timed: a2\nproviderchecks: NozzleExperimental.Cs1237ProviderFailureTests @ sysbus\n    throwingPort: p3\n    rangePort: p4\n    throwing: a3\n    range: a4\n';(d/'test.repl').write_text(repl)
 src=[root/'nozzle-renode/peripherals/AT32F403A_IO.cs',base.parent/'cs1237-native/Cs1237NativeGpio.cs']+[base/(n+'.cs')for n in ['Cs1237FunctionalProtocol','Cs1237FunctionalAdapter','Cs1237FunctionalTests','Cs1237BindingTests','Cs1237ProviderFailureTests']];lines=[f'include @{p}'for p in src]+['mach create "functional-unit-no-CPU"',f'machine LoadPlatformDescription @{d}/test.repl','sysbus.checks RunAll','sysbus.binding RunAll','sysbus.providerchecks Prepare','emulation RunFor "0.30201"','sysbus.providerchecks Finish','quit'];(d/'test.resc').write_text('\n'.join(lines)+'\n')
 env=dict(os.environ,HOME=str(d/'home'),XDG_CONFIG_HOME=str(d/'home/.config'),TMPDIR=str(d));r=subprocess.run([str(root/'at32-runtime/renode_1.17.0-portable/renode'),'--disable-gui','--console',str(d/'test.resc')],env=env,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,text=True,timeout=45)
 (out/'unit-tests.log').write_text(r.stdout);assert r.returncode==0 and 'CS1237 FUNCTIONAL TESTS PASS: 42'in r.stdout and 'CS1237 FUNCTIONAL BINDING TESTS PASS: 14'in r.stdout and 'CS1237 PROVIDER FAILURE TESTS PASS: 14'in r.stdout,r.stdout;print('CS1237 FUNCTIONAL TESTS PASS:42');(out/'unit-tests.json').write_text(json.dumps({'protocol_checks':42,'binding_checks':14,'provider_failure_checks':14,'source_hashes':{str(p.relative_to(root)):hashlib.sha256(p.read_bytes()).hexdigest()for p in src}},indent=2)+'\n')
